<script setup lang="ts">
import {useRoute,useRouter} from 'vue-router'
import {onMounted,onUnmounted,ref,computed} from 'vue'
type Row={id:number;canonical_name:string;review_state:string;visibility_state:string;last_event_id:number;sha256?:string;locator?:unknown}
type Source={id:string;dataset:string;sha256:string;license_state:string;integrity_state:string;version_label:string}
const rows=ref<Row[]>([]),detail=ref<{plant:Row;sources:Source[];history:Record<string,unknown>[]} | null>(null),rationale=ref(''),nameChecked=ref(false),busy=ref(false),error=ref(''),notice=ref(''),confirm=ref<'RELEASE'|'WITHDRAW'|null>(null)
const route=useRoute(),router=useRouter()
let controller=new AbortController(),epoch=0
async function read<T>(path:string,init:RequestInit={}):Promise<T>{const r=await fetch('/api/v1/admin/science/catalog'+path,{...init,credentials:'include',signal:controller.signal,headers:{Accept:'application/json',...init.headers}});if(!r.ok)throw Error(r.status===409?'目录版本已变化，请重新读取并核对。':r.status===422?'来源、许可或人工核对条件未满足，请补充后重试。':`目录操作失败（${r.status}）`);return r.json()}
async function load(){try{rows.value=await read<Row[]>('')}catch(e){if(!controller.signal.aborted)error.value=(e as Error).message}}
async function select(id:number){const n=++epoch;detail.value=null;rationale.value='';nameChecked.value=false;confirm.value=null;error.value='';notice.value='';if(!Number.isSafeInteger(id)||id<1)return;void router.replace({query:{...route.query,catalogId:String(id)}});try{const d=await read<typeof detail.value>('/'+id);if(n===epoch)detail.value=d}catch(e){if(!controller.signal.aborted&&n===epoch)error.value=(e as Error).message}}
const ready=computed(()=>detail.value?.sources.length===1&&detail.value.sources.every(s=>s.license_state==='PERMITTED'&&s.integrity_state==='VERIFIED')&&nameChecked.value)
async function decide(){if(!detail.value||!confirm.value||busy.value)return;const d=detail.value,action=confirm.value;busy.value=true;error.value='';try{const r=await fetch('/api/v1/csrf',{credentials:'include',signal:controller.signal});if(!r.ok)throw Error('无法读取会话校验，请重新登录。');const csrf=await r.json();const result=await read<{eventId:number;state:string}>('/'+d.plant.id+'/decisions',{method:'POST',headers:{'Content-Type':'application/json',[csrf.headerName]:csrf.token},body:JSON.stringify({action,expectedEventId:d.plant.last_event_id,expectedScientificName:d.plant.canonical_name,expectedSourceSha256:d.plant.sha256,scientificNameConfirmed:nameChecked.value,rationale:rationale.value,requestId:crypto.randomUUID()})});await load();await select(d.plant.id);notice.value=`目录决定已保存：${result.state}，事件 ${result.eventId}。本操作没有批准形态或测量候选。`}catch(e){if(!controller.signal.aborted)error.value=(e as Error).message}finally{busy.value=false;confirm.value=null}}
onMounted(async()=>{await load();const id=Number(route.query.catalogId);if(Number.isSafeInteger(id)&&id>0)await select(id)});onUnmounted(()=>{epoch++;controller.abort()})
</script>
<template><details class="catalog-review"><summary>植物目录核对与发布 · 管理员专属</summary><p>目录开放、分类名称核对与科学观测审核是独立决定。请实际核对原始证据和展示许可；不会自动批准含油率、形态或脂肪酸。</p><p v-if="error" role="alert" class="review-alert">{{error}}</p><p v-if="notice" role="status" class="review-success">{{notice}}</p><label>选择目录记录<select :value="detail?.plant.id??''" :disabled="busy" @change="select(Number(($event.target as HTMLSelectElement).value))"><option value="">请选择植物</option><option v-for="p in rows" :value="p.id" :key="p.id">#{{p.id}} {{p.canonical_name}} · {{p.visibility_state}}</option></select></label><section v-if="detail"><h3>{{detail.plant.canonical_name}} · #{{detail.plant.id}}</h3><p>目录状态 {{detail.plant.review_state}} / {{detail.plant.visibility_state}} · 当前事件 {{detail.plant.last_event_id}}</p><p>来源定位：{{detail.plant.locator}} · SHA-256 {{detail.plant.sha256||'缺失'}}</p><ul><li v-for="s in detail.sources" :key="s.id">{{s.dataset}} · {{s.license_state}} / {{s.integrity_state}} · 版本 {{s.version_label}} <a v-if="s.license_state==='PERMITTED'&&s.integrity_state==='VERIFIED'" :href="`/api/v1/admin/science/sources/${s.id}/preview`" target="_blank" rel="noopener">受控证据预览 ↗</a></li></ul><p v-if="!detail.sources.length">没有可追溯的规范化来源，不允许发布。</p><p v-if="!detail.sources.every(s=>s.license_state==='PERMITTED')">公开许可尚未确认。请先在来源许可判断中实际核对并记录许可依据。</p><label><input v-model="nameChecked" :disabled="busy" type="checkbox"/> 我已实际核对上述学名和原始证据，确认目录分类身份。</label><label>目录决定依据<textarea v-model="rationale" :disabled="busy" rows="3" minlength="10" maxlength="8000" placeholder="记录核对依据及展示范围；至少10个字符"/></label><div class="catalog-actions"><button :disabled="busy||!ready||rationale.trim().length<10" @click="confirm='RELEASE'">核对发布目录</button><button :disabled="busy||rationale.trim().length<10" @click="confirm='WITHDRAW'">核对撤回目录</button></div><section v-if="confirm" class="state-notice state-notice--warning"><strong>确认 {{confirm==='RELEASE'?'发布':'撤回'}} #{{detail.plant.id}} {{detail.plant.canonical_name}}？</strong><p>当前真实登录账户将记入审核历史；不批准任何科学观测。</p><button :disabled="busy" @click="decide">确认提交目录决定</button><button :disabled="busy" @click="confirm=null">返回修改</button></section><details><summary>目录审核历史（{{detail.history.length}}）</summary><pre>{{JSON.stringify(detail.history,null,2)}}</pre></details></section></details></template>
<style scoped>.catalog-review{grid-column:1/-1;margin:18px 0;padding:18px;background:var(--paper);border:1px solid var(--line);min-width:0;overflow-wrap:anywhere}.catalog-review summary{cursor:pointer;font-weight:600}.catalog-review p,.catalog-review li{font-size:12px;line-height:1.8}.catalog-review label{display:block;margin:12px 0;font-size:13px}.catalog-review select,.catalog-review textarea{display:block;padding:10px;width:100%;max-width:100%;border:1px solid var(--line);background:white}.catalog-review pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px}.catalog-actions{display:flex;flex-wrap:wrap;gap:10px}.catalog-review button{padding:10px 14px;background:var(--green-dark);color:white;border:0;cursor:pointer}.catalog-review button:disabled{opacity:.5;cursor:not-allowed}.catalog-review a{text-decoration:underline}</style>
